-- Time-series shape: declarative range, list and hash partitioning, identity columns,
-- GENERATED ALWAYS AS ... STORED columns.
-- Fixture for src/test/real-world-schemas.integration.test.ts; loaded into its own database.
CREATE TABLE devices (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, serial_no text NOT NULL UNIQUE, kind text NOT NULL);
CREATE TABLE metrics (device_id bigint NOT NULL, ts timestamptz NOT NULL, metric text NOT NULL, value double precision NOT NULL,
  value_x100 numeric GENERATED ALWAYS AS (round((value * 100)::numeric, 2)) STORED,
  PRIMARY KEY (device_id, ts, metric)) PARTITION BY RANGE (ts);
CREATE TABLE metrics_2026_01 PARTITION OF metrics FOR VALUES FROM ('2026-01-01') TO ('2026-02-01');
CREATE TABLE metrics_2026_02 PARTITION OF metrics FOR VALUES FROM ('2026-02-01') TO ('2026-03-01');
CREATE TABLE metrics_default PARTITION OF metrics DEFAULT;
CREATE INDEX metrics_metric_ts_idx ON metrics (metric, ts DESC);
-- list partitioning by region
CREATE TABLE events (id bigint GENERATED BY DEFAULT AS IDENTITY, region text NOT NULL, kind text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL DEFAULT now(),
  payload_size int GENERATED ALWAYS AS (octet_length(payload::text)) STORED,
  PRIMARY KEY (region, id)) PARTITION BY LIST (region);
CREATE TABLE events_eu PARTITION OF events FOR VALUES IN ('eu-west','eu-central');
CREATE TABLE events_us PARTITION OF events FOR VALUES IN ('us-east','us-west');
CREATE TABLE events_other PARTITION OF events DEFAULT;
-- sensor readings with generated column + FK to identity PK (non-partitioned child)
CREATE TABLE readings (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, device_id bigint NOT NULL REFERENCES devices(id),
  celsius numeric(5,2) NOT NULL, fahrenheit numeric GENERATED ALWAYS AS (celsius * 9 / 5 + 32) STORED,
  recorded_at timestamptz NOT NULL DEFAULT now());
-- hash-partitioned audit
CREATE TABLE audit_log (id bigint NOT NULL, actor text NOT NULL, action text NOT NULL, at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (id)) PARTITION BY HASH (id);
CREATE TABLE audit_log_p0 PARTITION OF audit_log FOR VALUES WITH (MODULUS 4, REMAINDER 0);
CREATE TABLE audit_log_p1 PARTITION OF audit_log FOR VALUES WITH (MODULUS 4, REMAINDER 1);
CREATE TABLE audit_log_p2 PARTITION OF audit_log FOR VALUES WITH (MODULUS 4, REMAINDER 2);
CREATE TABLE audit_log_p3 PARTITION OF audit_log FOR VALUES WITH (MODULUS 4, REMAINDER 3);
